module.exports = async (args) => {
  const jobLog = (m) => { try { args.jobLog(m); } catch (e) {} };
  const num = (v) => { const n = Number(v); return (isFinite(n) && n > 0) ? n : 0; };
  let mi = [];
  try { const t = args.inputFileObj.mediaInfo.track; mi = Array.isArray(t) ? t : [t]; } catch (e) { mi = []; }
  const ofType = (t) => mi.filter((x) => x && x['@type'] === t);
  let br = 0, src = '';
  try { const v = ofType('Video')[0] || {}; br = num(v.BitRate || v.BitRate_Nominal); if (br) src = 'mediainfo video track'; } catch (e) {}
  if (!br) { try { const g = ofType('General')[0] || {}; br = num(g.OverallBitRate || g.BitRate); if (br) src = 'mediainfo overall'; } catch (e) {} }
  if (!br) { try { br = num(args.inputFileObj.ffProbeData.format.bit_rate); if (br) src = 'ffprobe format'; } catch (e) {} }
  if (!br) {
    try {
      const sz = num(args.inputFileObj.file_size);
      const du = num(args.inputFileObj.ffProbeData.format.duration);
      if (sz && du) { br = Math.round(sz * 8 / du); src = 'size/duration estimate'; }
    } catch (e) {}
  }
  jobLog('Video bitrate: ' + (br ? Math.round(br / 1000) + ' kbps (' + src + ')' : 'unknown'));
  let out = 2;
  if (br > 0 && br <= 6000000) { out = 1; jobLog('At or below 6 Mbps, skipping transcode'); }
  else { jobLog('Above 6 Mbps (or unknown), will transcode'); }
  return { outputFileObj: args.inputFileObj, outputNumber: out, variables: args.variables };
};

module.exports = async (args) => {
  const jobLog = (m) => { try { args.jobLog(m); } catch (e) {} };
  const fc = args.variables && args.variables.ffmpegCommand;
  if (!fc || !Array.isArray(fc.streams)) throw new Error('FFmpeg command not initialised');
  const streams = fc.streams;
  const langMap = { en: 'eng', eng: 'eng', english: 'eng', hi: 'hin', hin: 'hin', hindi: 'hin',
    ja: 'jpn', jpn: 'jpn', japanese: 'jpn', fr: 'fra', fre: 'fra', fra: 'fra', french: 'fra' };
  const normLang = (raw) => {
    if (raw === undefined || raw === null) return '';
    const l = String(raw).trim().toLowerCase();
    if (langMap[l]) return langMap[l];
    return l;
  };
  const ffLang = (s) => { try { return normLang(s.tags && s.tags.language); } catch (e) { return ''; } };
  let miTracks = [];
  try { const t = args.inputFileObj.mediaInfo.track; miTracks = Array.isArray(t) ? t : [t]; } catch (e) { miTracks = []; }
  const miLang = (s) => {
    try {
      const type = s.codec_type === 'audio' ? 'Audio' : (s.codec_type === 'subtitle' ? 'Text' : 'Video');
      const same = streams.filter((x) => x.codec_type === s.codec_type);
      const cand = miTracks.filter((t) => t && t['@type'] === type);
      const tr = cand[same.indexOf(s)];
      if (!tr) return '';
      const keys = ['Language', 'Language_String', 'Language_ISO639', 'language'];
      for (let i = 0; i < keys.length; i += 1) { if (tr[keys[i]]) { const n = normLang(tr[keys[i]]); if (n) return n; } }
    } catch (e) {}
    return '';
  };
  const langOf = (s) => ffLang(s) || miLang(s);
  const audios = streams.filter((s) => s.codec_type === 'audio');
  const firstLang = audios.length > 0 ? langOf(audios[0]) : '';
  const keepLangs = ['eng', 'hin'];
  if (firstLang && firstLang !== 'und' && keepLangs.indexOf(firstLang) === -1) keepLangs.push(firstLang);
  jobLog('Audio keep languages: ' + keepLangs.join(', ') + (firstLang ? ' (first audio track: ' + firstLang + ')' : ''));
  const keptAudio = [];
  audios.forEach((s) => {
    const lang = langOf(s);
    const keep = !lang || lang === 'und' || keepLangs.indexOf(lang) !== -1;
    jobLog('Audio 0:' + s.index + ' codec=' + s.codec_name + ' ch=' + s.channels
      + ' lang=' + (lang || 'unknown') + ' -> ' + (keep ? 'keep' : 'drop'));
    if (keep) { keptAudio.push(s); } else { s.removed = true; }
  });
  const TEXT = ['subrip', 'ass', 'ssa', 'mov_text', 'webvtt', 'srt', 'ttml', 'stpp'];
  const IMAGE = ['hdmv_pgs_subtitle', 'dvd_subtitle', 'dvb_subtitle', 'dvdsub', 'xsub', 'pgs'];
  const subs = streams.filter((s) => s.codec_type === 'subtitle');
  const textLangs = [];
  subs.forEach((s) => {
    const codec = String(s.codec_name || '').toLowerCase();
    if (TEXT.indexOf(codec) !== -1) { const l = langOf(s); if (l && textLangs.indexOf(l) === -1) textLangs.push(l); }
  });
  subs.forEach((s) => {
    const codec = String(s.codec_name || '').toLowerCase();
    const lang = langOf(s);
    const isImage = IMAGE.indexOf(codec) !== -1;
    let keep = true;
    if (isImage) {
      keep = !(lang && lang !== 'und' && textLangs.indexOf(lang) !== -1);
    } else {
      keep = !lang || lang === 'und' || keepLangs.indexOf(lang) !== -1;
    }
    jobLog('Subtitle 0:' + s.index + ' codec=' + s.codec_name + ' lang=' + (lang || 'unknown')
      + ' -> ' + (keep ? 'keep' : 'drop'));
    if (!keep) s.removed = true;
  });
  const isAac = (s) => String(s.codec_name || '').toLowerCase().indexOf('aac') === 0;
  const hasAacStereo = keptAudio.some((s) => isAac(s) && Number(s.channels) === 2);
  if (!hasAacStereo && keptAudio.length > 0) {
    const sorted = keptAudio.slice().sort((a, b) => ((Number(b.channels) || 0) - (Number(a.channels) || 0)) || (a.index - b.index));
    const src = sorted[0];
    const srcLang = langOf(src);
    const aIdx = keptAudio.length;
    jobLog('Kept audio tracks: ' + keptAudio.length + ', new AAC audio index: ' + aIdx);
    const clone = JSON.parse(JSON.stringify(src));
    clone.mapArgs = ['-map', '0:' + src.index];
    clone.inputArgs = [];
    clone.outputArgs = ['-c:a:' + aIdx, 'aac', '-ac:a:' + aIdx, '2', '-b:a:' + aIdx, '160k'];
    if (srcLang && srcLang !== 'und') clone.outputArgs.push('-metadata:s:a:' + aIdx, 'language=' + srcLang);
    clone.removed = false;
    if (clone.disposition) { const d = {}; Object.keys(clone.disposition).forEach((k) => { d[k] = 0; }); clone.disposition = d; }
    streams.push(clone);
    jobLog('Added AAC stereo track from 0:' + src.index + ' (' + src.codec_name + ', ' + src.channels + 'ch, 160k)');
  } else {
    jobLog(hasAacStereo ? 'AAC stereo track already present' : 'No audio tracks to build AAC stereo from');
  }
  const video = streams.find((s) => s.codec_type === 'video');
  const height = video ? Number(video.height) || 0 : 0;
  const out = height > 720 ? 1 : 2;
  jobLog('Video height ' + height + ' -> ' + (out === 1 ? '1080p path (quality 23)' : '720p/SD path (quality 21)'));
  return { outputFileObj: args.inputFileObj, outputNumber: out, variables: args.variables };
};

module.exports = async (args) => {
  const jobLog = (m) => { try { args.jobLog(m); } catch (e) {} };
  const dur = (o) => {
    try { const d = Number(o && o.ffProbeData && o.ffProbeData.format && o.ffProbeData.format.duration); return d > 0 ? d : 0; }
    catch (e) { return 0; }
  };
  const nd = dur(args.inputFileObj);
  const od = dur(args.originalLibraryFile);
  const diff = Math.abs(nd - od);
  jobLog('Duration check: new=' + nd + 's original=' + od + 's diff=' + diff.toFixed(3) + 's');
  let out = 2;
  if (nd > 0 && od > 0 && diff <= 2) { out = 1; jobLog('Duration within 2 s, proceeding to replace'); }
  else { jobLog('Duration differs by more than 2 s (or is unreadable), keeping original'); }
  return { outputFileObj: args.inputFileObj, outputNumber: out, variables: args.variables };
};
